INSERT OR REPLACE INTO cards (id, name, name_cn, name_jp, type, race, attribute, level, atk, def, desc_cn) VALUES
(11755663, 'Dinowrestler Martial Anga', '恐龙摔跤手・武术崇高龙', 'ダイナレスラー・マーシャルアンガ', 'Effect Monster', 'Dinosaur', 'EARTH', 5, 1600, NULL, '①：自己的「恐龙摔跤手」怪兽和持有那个攻击力以上的攻击力的怪兽进行战斗的伤害计算时，把这张卡从手卡送去墓地才能发动。那只自己怪兽不会被那次战斗破坏，那次伤害步骤结束后战斗阶段结束。 ②：这张卡为这张卡的效果发动而被送去墓地的回合的结束阶段，对方场上的怪兽数量比自己场上的怪兽多的场合才能发动。这张卡特殊召唤。'),
(35770983, 'Dinowrestler Martial Ankylo', '恐龙摔跤手・武术甲龙', 'ダイナレスラー・マーシャルアンキロ', 'Effect Monster', 'Dinosaur', 'EARTH', 2, 1000, NULL, '这个卡名的②的效果1回合只能使用1次。 ①：这张卡以外的自己的「恐龙摔跤手」怪兽和对方怪兽进行战斗的伤害计算时，把手卡·场上的这张卡送去墓地才能发动。那只自己怪兽不会被那次战斗破坏，那只对方怪兽的攻击力在伤害步骤结束时变成一半。 ②：这张卡从场上送去墓地的回合的结束阶段才能发动。这张卡特殊召唤。这个效果特殊召唤的这张卡从场上离开的场合除外。'),
(82385847, 'Dinowrestler Pankratops', '恐龙摔跤手・潘克拉三角龙', 'ダイナレスラー・パンクラトプス', 'Effect Monster', 'Dinosaur', 'EARTH', 7, 2600, NULL, '这个卡名的①的方法的特殊召唤1回合只能有1次，②的效果1回合只能使用1次。 ①：对方场上的怪兽数量比自己场上的怪兽多的场合，这张卡可以从手卡特殊召唤。 ②：自己·对方回合，把自己场上1只「恐龙摔跤手」怪兽解放，以对方场上1张卡为对象才能发动。那张卡破坏。'),
(61764082, 'Dinowrestler Rambrachio', '恐龙摔跤手・朗搏腕龙', 'ダイナレスラー・ラアムブラキオ', 'Effect Monster', 'Dinosaur', 'EARTH', 5, 1600, NULL, '这个卡名的①的效果1回合只能使用1次。 ①：自己的「恐龙摔跤手」怪兽给与对方战斗伤害时才能发动。这张卡从手卡守备表示特殊召唤。 ②：只要这张卡在怪兽区域存在，自己场上的其他的「恐龙摔跤手」怪兽不会成为对方的效果的对象。'),
(56980148, 'Dinowrestler Systegosaur', '恐龙摔跤手・西斯特玛剑龙', 'ダイナレスラー・システゴ', 'Effect Monster', 'Dinosaur', 'EARTH', 4, 1900, NULL, '这个卡名的①②的效果1回合各能使用1次。 ①：这张卡特殊召唤成功的场合才能发动。从卡组把1只「恐龙摔跤手」怪兽或者1张「世界恐龙摔跤」加入手卡。 ②：这张卡被送去墓地的回合的结束阶段，对方场上的怪兽数量比自己场上的怪兽多的场合，以「恐龙摔跤手·西斯特玛剑龙」以外的自己墓地1只「恐龙摔跤手」怪兽为对象才能发动。那只怪兽特殊召唤。'),
(69121954, 'Dinowrestler Terra Parkourio', '恐龙摔跤手・太拉・跑酷冰脊龙', 'ダイナレスラー・テラ・パルクリオ', 'Link Monster', 'Dinosaur', 'EARTH', NULL, 1000, NULL, '「恐龙摔跤手」怪兽2只 这个卡名的①②的效果1回合各能使用1次。 ①：自己把「世界恐龙摔跤」发动的场合，以自己墓地1只「恐龙摔跤手」怪兽为对象才能发动。那只怪兽加入手卡。 ②：这张卡作为连接素材送去墓地的场合，以自己墓地1只「恐龙摔跤手」怪兽为对象才能发动。那只怪兽效果无效守备表示特殊召唤。这个回合，自己不是「恐龙摔跤手」怪兽不能特殊召唤。'),
(80831552, 'Dinowrestler Valeonyx', '恐龙摔跤手・综合格斗重爪龙', 'ダイナレスラー・バーリオニクス', 'Effect Monster', 'Dinosaur', 'EARTH', 3, 1600, NULL, '①：只有对方场上才有怪兽存在的场合，这张卡可以从手卡特殊召唤。 ②：只要自己场上有连接3以上的「恐龙摔跤手」怪兽存在，自己场上的表侧表示怪兽不受连接3以下的对方怪兽发动的效果影响。'),
(46533533, 'Dipity', '皮缇', 'ピティ', 'Normal Monster', 'Fiend', 'LIGHT', 4, NULL, NULL, '据说会给契约人带来幸运，住在玻璃瓶中的可爱小家伙。那个盖子绝对不能打开。不管发生什么事都绝对…。'),
(78084378, 'Diplexer Chimera', '信号分离器客迈拉', 'ダイプレクサ・キマイラ', 'Fusion Monster', 'Cyberse', 'LIGHT', 5, 2000, 800, '电子界族怪兽×2 这个卡名的②的效果1回合只能使用1次。 ①：1回合1次，把自己场上1只电子界族怪兽解放才能发动。这个回合的战斗阶段中双方不能把魔法·陷阱卡的效果发动。 ②：融合召唤的这张卡被送去墓地的场合，以这张卡以外的自己墓地1只电子界族怪兽和1张「电脑网融合」为对象才能发动。那些卡加入手卡。'),
(66472129, 'Dipsea Fiend', '深海魔鬼', 'ディプシーデビル', 'Effect Monster', 'Fiend', 'WATER', 4, 1500, 1000, '这个卡名的效果1回合只能使用1次。 ①：丢弃1张手卡，宣言1个水属性以外的属性才能发动。这张卡从手卡往自己或对方的场上特殊召唤。那之后，这张卡的属性直到回合结束时变成宣言的属性。这个效果在对方场上特殊召唤的场合，可以再把原本属性和宣言的属性不同的1只4星以下的恶魔族怪兽从自己的手卡·墓地往自己场上特殊召唤。这个效果的发动后，直到回合结束时自己不是恶魔族怪兽不能从额外卡组特殊召唤。'),
(40971261, 'Dirge of the Lost Dragon', '亡龙之旋律', '亡龍の旋律', 'Spell Card', 'Continuous', NULL, NULL, NULL, NULL, '宣言1个卡名才能把这张卡发动。 ①：只要这张卡在魔法与陷阱区域存在，每次宣言的卡的效果发动，把那个效果发动的卡的原本持有者的基本分变成一半。这个效果适用的回合的结束阶段这张卡送去墓地。 ②：对方场上有怪兽存在的场合，这张卡不会被效果破坏。'),
(58707981, 'Disablaster the Negation Fortress', '无孔炮塔－失能爆裂炮', '無孔砲塔－ディセイブラスター', 'Pendulum Effect Monster', 'Machine', 'LIGHT', 5, 500, 2000, '这个卡名的①的方法的特殊召唤1回合只能有1次。 ①：有着没有卡存在的纵列的场合，这张卡可以从手卡往那个纵列的自己场上特殊召唤。 ②：只要这张卡在怪兽区域存在，和这张卡相同纵列发动的魔法·陷阱·怪兽的效果无效化。 ③：怪兽区域的这张卡被破坏的场合才能发动。这张卡在自己的灵摆区域放置。'),
(24623598, 'Disappear', '失落', 'ロスト', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '选择对方墓地的1张卡从游戏中除外。'),
(26834022, 'Disarm', '卸除武器', 'ディザーム', 'Trap Card', 'Counter', NULL, NULL, NULL, NULL, '从手卡把1张名字带有「剑斗兽」的卡回到卡组。魔法卡的发动无效并破坏。'),
(20727787, 'Disarmament', '武装解除', '武装解除', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '将场上的装备卡全部破坏。'),
(67359907, 'Disaster, Dragon Ruler of All Apocalypses', '超征龙－灾异', '超征竜－ディザスター', 'XYZ Monster', 'Dragon', 'LIGHT', 7, NULL, NULL, '7阶怪兽×2 这个卡名的①的效果1回合只能使用1次。 ①：这张卡超量召唤的场合，以自己的墓地·除外状态的最多4只7星「征龙」怪兽为对象才能发动。那些怪兽作为这张卡的超量素材。那之后，可以把持有和给这张卡作为超量素材中的怪兽相同属性的怪兽从对方的场上·墓地全部除外。 ②：有光·暗·地·水·炎·风属性的「征龙」怪兽全部在作为超量素材中的这张卡攻击力·守备力上升4600，不受其他卡的效果影响。'),
(19612721, 'Disc Fighter', '圆盘斗士', '円盤闘士', 'Effect Monster', 'Warrior', 'EARTH', 4, 1000, 1000, '这张卡对守备力2000以上的守备表示怪兽进行攻击时，不经过损伤计算而直接将其破坏。'),
(98999181, 'Disciple of Nephthys', '奈芙蒂斯的祈祷者', 'ネフティスの祈り手', 'Effect Monster', 'Spellcaster', 'WIND', 2, NULL, 2000, '这个卡名的①②的效果1回合各能使用1次。 ①：自己主要阶段才能发动。选1张手卡破坏，从卡组把「奈芙提斯之祈祷者」以外的1只「奈芙提斯」怪兽加入手卡。 ②：这张卡被效果破坏送去墓地的场合，下次的自己准备阶段才能发动。从卡组把1张「奈芙提斯」魔法·陷阱卡加入手卡。'),
(15595052, 'Disciple of the Forbidden Spell', '封魔之传承者', '封魔の伝承者', 'Effect Monster', 'Warrior', 'LIGHT', 4, 1700, 800, '这张卡召唤·反转召唤·特殊召唤成功时，宣言和自己墓地存在的「封魔之传承者」同数目的属性。这张卡对宣言属性的怪兽进行攻击的场合，不进行伤害计算直接破坏那只怪兽。'),
(75425320, 'Disciples of the True Dracophoenix', '真龙凰的使徒', '真竜凰の使徒', 'Spell Card', 'Continuous', NULL, NULL, NULL, NULL, '这个卡名的①②③的效果1回合各能使用1次。 ①：以自己墓地3张「真龙」卡为对象才能发动。那些卡回到卡组。那之后，自己抽1张。 ②：自己主要阶段才能发动。表侧表示进行1只「真龙」怪兽的上级召唤。 ③：这张卡从魔法与陷阱区域送去墓地的场合，以场上1张魔法·陷阱卡为对象才能发动。那张卡破坏。'),
(46480475, 'Discord', '不协和音', '不協和音', 'Trap Card', 'Continuous', NULL, NULL, NULL, NULL, '双方玩家不能同调召唤。发动后第3次的自己的结束阶段时这张卡送去墓地。'),
(86553594, 'Discordance of the Tistina', '提斯蒂娜的变晶', 'ティスティナの変晶', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的①②的效果1回合只能有1次使用其中任意1个。 ①：可以从以下效果选择1个发动。 ●自己场上有「提斯蒂娜」怪兽存在的场合才能发动。对方墓地1张卡里侧除外。 ●从额外卡组特殊召唤的「提斯蒂娜」怪兽在自己场上存在的场合才能发动。对方墓地的卡全部里侧除外。 ②：把墓地的这张卡除外，以自己墓地1只「提斯蒂娜」怪兽为对象才能发动。那只怪兽回到手卡。'),
(76137614, 'Disenchanter', '圣解咒师', '聖なる解呪師', 'Effect Monster', 'Spellcaster', 'LIGHT', 5, 2000, 2300, '①：1回合1次，以场上1张表侧表示的魔法卡为对象才能发动。场上1个魔力指示物取除，作为对象的表侧表示的卡回到持有者手卡。'),
(87750925, 'Disguise, the Copycat Hero', '效仿英杰 伪装者', NULL, 'Tuner Monster', 'Warrior', 'LIGHT', 4, 1400, 1200, '自己场上或墓地有装备魔法卡存在的场合：可以把这张卡从手卡特殊召唤。 这张卡召唤·特殊召唤的场合：可以从卡组把1张「咒怨仿品·圣剑」加入手卡。 这张卡有装备卡装备中的场合：可以以场上1只持有等级的调整以外的战士族怪兽为对象；这张卡的等级和卡名直到回合结束时变成和那只怪兽相同。 「效仿英杰 伪装者」的每个效果1回合各能使用1次。'),
(76446915, 'Disk Magician', '圆盘魔术师', 'ディスク・マジシャン', 'Normal Monster', 'Machine', 'DARK', 4, 1350, 1000, '将自己封印在铁盘里，攻击时才露出本体。'),
(41113025, 'Diskblade Rider', '圆盘骑手', 'ディスクライダー', 'Effect Monster', 'Fiend', 'WIND', 4, 1700, 1500, '把自己墓地存在的1张通常陷阱卡从游戏中除外，这张卡的攻击力直到对方回合的结束阶段时上升500。这个效果1回合只能使用1次。'),
(64966519, 'Dispatchparazzi', '激摄特派狗仔队', '激撮ディスパラッチ', 'Link Monster', 'Fiend', 'DARK', NULL, 100, NULL, '效果怪兽2只 这个卡名的①②的效果1回合各能使用1次。 ①：这张卡以外的自己怪兽被选择作为攻击对象时才能发动。攻击对象转移为这张卡进行伤害计算。 ②：这张卡被和对方怪兽的战斗破坏时才能发动。那只对方怪兽破坏，自己基本分回复那个原本攻击力一半的数值。'),
(42149850, 'Disposable Learner Device', '一次性学习装置', '使い捨て学習装置', 'Spell Card', 'Equip', NULL, NULL, NULL, NULL, '这个卡名的②的效果1回合只能使用1次。 ①：装备怪兽的攻击力上升自己墓地的怪兽数量×200。 ②：这张卡从场上送去墓地的回合的结束阶段才能发动。这张卡在自己场上盖放。这个效果盖放的这张卡从场上离开的场合除外。'),
(40826495, 'Dissolverock', '岩浆人', 'マグマン', 'Normal Monster', 'Rock', 'EARTH', 3, 900, 1000, '岩浆里出生的怪兽，灼热的身体使接近的物体融化。'),
(77561728, 'Disturbance Strategy', '搅乱作战', '攪乱作戦', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '对方将手卡加入卡组，再从卡组抽出与原本手卡数一样数目的卡。'),
(90448279, 'Divine Arsenal AA-ZEUS - Sky Thunder', '神灭兵器－天霆号 扼宙斯', '天霆號アーゼウス', 'XYZ Monster', 'Machine', 'LIGHT', 12, 3000, 3000, '12星怪兽×2 「天霆号 阿宙斯」在超量怪兽进行过战斗的回合有1次也能在自己场上的超量怪兽上面重叠来超量召唤。 ①：自己·对方回合，把这张卡2个超量素材取除才能发动。场上的其他卡全部送去墓地。 ②：1回合1次，自己场上的其他卡被战斗或者对方的效果破坏的场合才能发动。从手卡·卡组·额外卡组把1张卡作为这张卡的超量素材。'),
(12397569, 'Divine Domain Baatistina', '神域 巴提斯蒂娜', '神域 バ＝ティスティナ', 'Spell Card', 'Field', NULL, NULL, NULL, NULL, '这个卡名的①的效果1回合只能使用1次。 ①：自己主要阶段才能发动。从卡组把1只「提斯蒂娜」怪兽送去墓地。对方场上有表侧表示卡3张以上存在的场合，可以再从手卡·卡组把1只「结晶神 提斯蒂娜」特殊召唤。 ②：场地区域的这张卡被对方的效果破坏的场合才能发动。从自己的卡组·墓地把1只「提斯蒂娜」怪兽特殊召唤。'),
(10032958, 'Divine Dragon - Excelion', '神龙-艾克塞利翁', '神竜－エクセリオン', 'Effect Monster', 'Dragon', 'LIGHT', 5, 1500, 900, '这张卡召唤时自己墓地存在的「神龙-艾克塞利翁」每有1只，得到以下的其中1个效果。但是相同的效果不能重复得到。 ●这张卡攻击力上升1000。 ●这张卡战斗破坏对方怪兽的场合，只有1次可以再度攻击。 ●这张卡战斗破坏怪兽送去墓地时，给与对方基本分破坏怪兽的攻击力数值的伤害。'),
(20277376, 'Divine Dragon Apocralyph', '神龙 天启', '神竜 アポカリプス', 'Effect Monster', 'Dragon', 'DARK', 4, 1000, 1500, '1回合1次，丢弃1张手卡才能发动。选择自己墓地1只龙族怪兽加入手卡。'),
(67964209, 'Divine Dragon Aquabizarre', '神龙 阿库阿巴扎', '神竜アクアバザル', 'Effect Monster', 'Sea Serpent', 'WATER', 5, 2100, 1500, '把这张卡以外的自己场上表侧表示存在的1只水属性怪兽解放，选择自己墓地存在的1张永续魔法或者场地魔法卡发动。选择的卡从自己墓地回到卡组最上面。这个效果1回合只能使用1次。'),
(1639384, 'Divine Dragon Knight Felgrand', '神龙骑士 绯尔格兰特', '神竜騎士フェルグラント', 'XYZ Monster', 'Warrior', 'LIGHT', 8, 2800, 1800, '8星怪兽×2 ①：1回合1次，把这张卡1个超量素材取除，以场上1只表侧表示怪兽为对象才能发动。这个回合，作为对象的怪兽效果无效，不受这张卡以外的效果影响。这个效果在对方回合也能发动。'),
(60681103, 'Divine Dragon Lord Felgrand', '巨神龙 闪耀', '巨神竜フェルグラント', 'Effect Monster', 'Dragon', 'LIGHT', 8, 2800, 2800, '①：这张卡从墓地的特殊召唤成功的场合，以对方的场上·墓地1只怪兽为对象才能发动。那只怪兽除外，这张卡的攻击力·守备力上升除外的那只怪兽的等级或者阶级×100。 ②：这张卡战斗破坏对方怪兽的场合，以「巨神龙 闪耀」以外的自己或者对方的墓地1只7·8星的龙族怪兽为对象才能发动。那只怪兽在自己场上特殊召唤。'),
(62113340, 'Divine Dragon Ragnarok', '神龙 诸神黄昏', '神竜 ラグナロク', 'Normal Monster', 'Dragon', 'LIGHT', 4, 1500, 1000, '被传为神使的传说之龙。触犯了它的怒火之时，据说世界会沉入海中。'),
(32975247, 'Divine Dragon Titanomakhia', '神龙 伟战龙', '神竜 ティタノマキア', 'Effect Monster', 'Dragon', 'LIGHT', 10, 3000, 2000, '这个卡名的②③的效果1回合各能使用1次。 ①：特殊召唤的这张卡不会被战斗破坏。 ②：从自己墓地以及自己场上的表侧表示怪兽之中把包含场上的这张卡的3只「神龙 伟战龙」除外才能发动。对方场上的卡全部破坏。 ③：自己·对方的结束阶段才能发动。把自己场上的龙族怪兽数量的卡从自己卡组上面送去墓地。'),
(89907228, 'Divine Dragon Token', '白斗气双头神龙', '白闘気双頭神龍', 'Token', 'Fish', NULL, NULL, NULL, NULL, NULL),
(7373632, 'Divine Evolution', '神之进化', '神の進化', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '这张卡的发动和效果不会被无效化。 ①：选自己场上1只原本种族是幻神兽族的怪兽或者原本卡名是「邪神 神之化身」「邪神 恐惧之源」「邪神 抹灭者」的怪兽（已受「神之进化」的效果适用的怪兽不能选）。那只怪兽攻击力·守备力上升1000，自身的效果的发动以及那些发动的效果不会被无效化，得到以下效果。 ●这张卡的攻击宣言时才能发动。对方必须把自身场上1只怪兽送去墓地。'),
(44698398, 'Divine Golden Shadow Dragon Dragluxion', '神影金龙 胶子光龙', '神影金龍ドラッグルクシオン', 'XYZ Monster', 'Dragon', 'LIGHT', 8, 2500, 3000, '8星怪兽×2 这个卡名的①②的效果1回合各能使用1次。 ①：这张卡从额外卡组特殊召唤的场合才能发动。从卡组把1张「银河」卡或「时空」卡加入手卡。 ②：把这张卡2个超量素材取除才能发动。把1只龙族·8阶·攻击力3000的超量怪兽在自己场上的这张卡上面重叠当作超量召唤从额外卡组特殊召唤。那之后，可以从额外卡组把1只「银河」怪兽作为那超量素材。'),
(61757117, 'Divine Grace - Northwemko', '救世之美神 诺斯维姆科', '救世の美神ノースウェムコ', 'Ritual Effect Monster', 'Spellcaster', 'LIGHT', 7, 2700, 1200, '「救世的仪式」降临。这张卡仪式召唤成功时，选择最多有这张卡的仪式召唤使用的怪兽数量的这张卡以外的场上表侧表示存在的卡发动。只要选择的卡在场上表侧表示存在，这张卡不会被卡的效果破坏。'),
(57902462, 'Divine Knight Ishzark', '圣导骑士 伊什扎克', '聖導騎士イシュザーク', 'Effect Monster', 'Warrior', 'LIGHT', 6, 2300, 1800, '这张卡战斗破坏怪兽时，那只怪兽从游戏中除外。'),
(81066751, 'Divine Punishment', '神罚', '神罰', 'Trap Card', 'Counter', NULL, NULL, NULL, NULL, '①：场上有「天空的圣域」存在，怪兽的效果·魔法·陷阱卡发动时才能发动。那个发动无效并破坏。'),
(89914395, 'Divine Relic Mjollnir', '米约尔尼尔之魔槌', 'ミョルニルの魔槌', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '选择自己场上表侧表示存在的1只名字带有「极神」的怪兽发动。这个回合，选择的怪兽在同1次的战斗阶段中可以作2次攻击。'),
(23804920, 'Divine Scorpion Beast of Serket', '圣神兽 塞尔凯特', '聖神獣セルケト', 'Fusion Monster', 'Fairy', 'EARTH', 6, 3000, 2000, '「塞勒凯特」怪兽＋攻击力2500以下的怪兽 这个卡名的①的效果1回合只能使用1次。 ①：这张卡特殊召唤的场合或者这张卡和对方怪兽进行战斗的伤害步骤开始时，以对方的场上（表侧表示）·墓地1只怪兽为对象才能发动。那只怪兽除外，这张卡的攻击力上升除外的怪兽的原本攻击力一半数值。 ②：只要10星以上的怪兽除外中，这张卡在同1次的战斗阶段中可以作2次攻击。'),
(97800311, 'Divine Serpent Apophis', '圣神蛇 阿波菲斯', '聖神蛇アポピス', 'Fusion Monster', 'Reptile', 'EARTH', 6, 2800, 2600, '有「王家的神殿」的卡名记述的怪兽×2 这张卡用融合召唤以及以下方法才能特殊召唤。 ●把自己场上2只「阿匹卜」怪兽解放的场合可以从额外卡组特殊召唤。 ①：1回合1次，以自己墓地最多3张「阿匹卜」陷阱卡为对象才能发动（同名卡最多1张）。那些卡在自己场上盖放。 ②：1回合1次，陷阱卡发动的场合，以对方场上1张卡为对象才能发动。那张卡破坏。'),
(82103466, 'Divine Serpent Geh', '蛇神 格', '蛇神ゲー', 'Effect Monster', 'Reptile', 'DARK', 12, -1, NULL, '这张卡不能通常召唤，用这张卡的效果才能特殊召唤。 ①：自己场上的怪兽被对方的攻击·效果破坏的场合，把基本分支付一半才能发动。这张卡从手卡特殊召唤。 ②：这张卡不会成为效果的对象。 ③：这张卡向对方怪兽攻击的伤害步骤内，那只怪兽的效果无效化，攻击力变成原本攻击力的一半。 ④：这张卡进行战斗的伤害计算时才能发动。这张卡的攻击力变成和场上的怪兽的最高原本攻击力相同。'),
(31423101, 'Divine Sword - Phoenix Blade', '神剑-凤凰剑', '神剣－フェニックスブレード', 'Spell Card', 'Equip', NULL, NULL, NULL, NULL, '战士族才能装备。装备怪兽的攻击力上升300。这张卡在自己的主要阶段存在于自己的墓地时，可以把自己墓地的2只战士族从游戏中除外，这张卡加入手卡。'),
(53639887, 'Divine Temple of the Snake-Eye', '蛇眼神殿', '蛇眼神殿スネークアイ', 'Spell Card', 'Field', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：作为这张卡的发动时的效果处理，可以从自己的手卡·卡组·墓地把1只「蛇眼」怪兽当作永续魔法卡使用在原本持有者的魔法与陷阱区域表侧表示放置。 ②：自己场上的炎属性·1星怪兽的攻击力上升1100。 ③：1回合1次，对方把怪兽召唤·特殊召唤的场合，以自己·对方场上1张当作永续魔法卡使用的怪兽卡为对象才能发动。那张卡在自己场上特殊召唤。'),
(15854426, 'Divine Wind of Mist Valley', '霞之谷的神风', '霞の谷の神風', 'Spell Card', 'Field', NULL, NULL, NULL, NULL, '自己场上表侧表示存在的风属性怪兽回到手卡的场合，可以从自己卡组把1只4星以下的风属性怪兽特殊召唤。这个效果1回合只能使用1次。'),
(49010598, 'Divine Wrath', '天罚', '天罰', 'Trap Card', 'Counter', NULL, NULL, NULL, NULL, '丢弃1张手卡发动。效果怪兽的效果的发动无效并破坏。'),
(92919429, 'Diviner of the Herald', '宣告者之神巫', '宣告者の神巫', 'Tuner Monster', 'Fairy', 'LIGHT', 2, 500, 300, '这个卡名的①②的效果1回合各能使用1次。 ①：这张卡召唤·特殊召唤成功的场合才能发动。从卡组·额外卡组把1只天使族怪兽送去墓地。这张卡的等级直到回合结束时上升那只怪兽的等级数值。 ②：这张卡被解放的场合才能发动。从手卡·卡组把「宣告者的神巫」以外的1只2星以下的天使族怪兽特殊召唤。'),
(42427230, 'Division', '分裂机器人', 'ディーヴジャン', 'Effect Monster', 'Machine', 'FIRE', 2, 200, 200, '这个卡名的①②的效果1回合各能使用1次。 ①：把自己场上的表侧表示的「分裂机器人」全部解放才能发动。把最多有解放数量×2只的「机械衍生物」（机械族·炎·1星·攻/守200）在自己场上特殊召唤。这衍生物被破坏时对方受到每1只500伤害。 ②：这张卡被除外的场合，以自己场上的衍生物任意数量为对象才能发动。那衍生物破坏。'),
(62681049, 'Dizzying Winds of Yosen Village', '妖仙乡的眩晕风', '妖仙郷の眩暈風', 'Trap Card', 'Continuous', NULL, NULL, NULL, NULL, '自己场上有6星以上的「妖仙兽」怪兽存在的场合才能把这张卡发动。 ①：只要这张卡在魔法与陷阱区域存在并在自己的灵摆区域有「妖仙兽」卡存在，场上盖放的怪兽以及除「妖仙兽」怪兽以外的场上的表侧表示怪兽因效果回到手卡的场合，不回到手卡回到持有者卡组。'),
(77153811, 'Djinn Cursenchanter of Rituals', '仪式魔人 诅咒魔法师', '儀式魔人カースエンチャンター', 'Effect Monster', 'Fiend', 'DARK', 4, 1700, 1000, '仪式怪兽的仪式召唤进行的场合，可以作为那次仪式召唤需要的等级数值的1只怪兽，把墓地存在的这张卡从游戏中除外。把这张卡在仪式召唤使用的仪式怪兽只要在场上表侧表示存在，同调怪兽的效果无效化。'),
(33145233, 'Djinn Demolisher of Rituals', '仪式魔人 摧毁者', '儀式魔人デモリッシャー', 'Effect Monster', 'Fiend', 'DARK', 3, 1500, 600, '①：仪式召唤进行的场合，可以作为那次仪式召唤需要的等级数值的1只怪兽，把墓地的这张卡除外。 ②：使用这张卡仪式召唤的怪兽不会成为对方的效果的对象。'),
(30492798, 'Djinn Disserere of Rituals', '仪式魔人 布置者', '儀式魔人ディザーズ', 'Effect Monster', 'Fiend', 'DARK', 1, 200, 200, '仪式怪兽的仪式召唤进行的场合，可以作为那次仪式召唤需要的等级数值的1只怪兽，把墓地存在的这张卡从游戏中除外。把这张卡在仪式召唤使用的仪式怪兽不受陷阱卡的效果影响。'),
(34358408, 'Djinn Presider of Rituals', '仪式魔人 主持者', '儀式魔人プレサイダー', 'Effect Monster', 'Fiend', 'DARK', 4, 1800, 1400, '仪式怪兽的仪式召唤进行的场合，可以作为那次仪式召唤需要的等级数值的1只怪兽，把墓地存在的这张卡从游戏中除外。把这张卡在仪式召唤使用的仪式怪兽战斗破坏怪兽的场合，那只仪式怪兽的控制者从卡组抽1张卡。'),
(4141820, 'Djinn Prognosticator of Rituals', '仪式魔人 预知者', '儀式魔人プレコグスター', 'Effect Monster', 'Fiend', 'DARK', 3, 400, 300, '仪式怪兽的仪式召唤进行的场合，可以作为那次仪式召唤需要的等级数值的1只怪兽，把墓地存在的这张卡从游戏中除外。把这张卡在仪式召唤使用的仪式怪兽给与对方基本分战斗伤害时，对方选择1张手卡丢弃。'),
(8903700, 'Djinn Releaser of Rituals', '仪式魔人 解放者', '儀式魔人リリーサー', 'Effect Monster', 'Fiend', 'DARK', 3, 1200, 2000, '①：仪式召唤进行的场合，可以作为那次仪式召唤需要的等级数值的1只怪兽，把墓地的这张卡除外。 ②：从使用这张卡仪式召唤的玩家来看的对方，只要仪式召唤的那只怪兽在怪兽区域表侧表示存在，不能把怪兽特殊召唤。'),
(97843505, 'Djinn the Watcher of the Wind', '风之番人 精', '風の番人 ジン', 'Normal Monster', 'Spellcaster', 'WIND', 3, 700, 900, '操纵风并产生龙卷风与飓风吹飞周围的东西。'),
(98371278, 'DMZ Dragon', 'DMZ龙', 'DMZドラゴン', 'Effect Monster', 'Dragon', 'DARK', 4, NULL, 2000, '①：1回合1次，以自己墓地1只4星以下的龙族怪兽和自己场上1只龙族怪兽为对象才能发动。作为对象的墓地的怪兽当作攻击力上升500的装备卡使用给作为对象的场上的怪兽装备。 ②：有装备卡装备的自己怪兽攻击的伤害步骤结束时，把墓地的这张卡除外才能发动。那只自己怪兽的装备卡全部破坏。破坏的场合，那只怪兽只再1次可以继续攻击。'),
(27340877, 'DNA Checkup', 'DNA定期健诊', 'DNA定期健診', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '选择自己场上里侧表示存在的1只怪兽发动。对方宣言2个怪兽的属性。选择怪兽翻开确认是宣言属性的场合，对方从卡组抽2张卡。不是的场合，自己从卡组抽2张卡。'),
(74701381, 'DNA Surgery', 'DNA改造手术', 'DNA改造手術', 'Trap Card', 'Continuous', NULL, NULL, NULL, NULL, '发动时宣言1个种族。只要这张卡在场上存在，场上的全部表侧表示的怪兽变成宣言的种族。'),
(56769674, 'DNA Transplant', 'DNA移植手术', 'DNA移植手術', 'Trap Card', 'Continuous', NULL, NULL, NULL, NULL, '这张卡发动时，宣言1种属性。这张卡在场上存在时，场上所有表侧表示的怪兽全部变成被宣言的属性。'),
(6260554, 'Do a Barrel Roll', '弹幕回避', '弾幕回避', 'Trap Card', 'Counter', NULL, NULL, NULL, NULL, '把自己场上的「幻兽机衍生物」全部解放才能发动。效果怪兽的效果·魔法·陷阱卡的发动无效并破坏。'),
(79997591, 'Doble Passe', '二重巴塞舞姿', 'ドゥーブルパッセ', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '①：对方怪兽向自己场上的表侧攻击表示怪兽攻击宣言时才能发动。给与对方为攻击对象怪兽的攻击力数值的伤害，那只对方怪兽的攻击变成向自己的直接攻击。那只自己怪兽在下次的自己回合可以直接攻击。'),
(22171591, 'Doctor Cranium', '秘学家', 'カバリスト', 'Effect Monster', 'Psychic', 'EARTH', 1, 100, 100, '这张卡被战斗破坏送去墓地时，可以支付800基本分从自己卡组把1只念动力族怪兽加入手卡。'),
(32671443, 'Doctor D', '博士D', 'ドクターD', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '①：从自己墓地把1只「命运英雄」怪兽除外才能发动。从自己墓地选1只「命运英雄」怪兽加入手卡或特殊召唤。 ②：把墓地的这张卡除外，以自己场上2只「命运英雄」怪兽为对象才能发动。作为对象的1只怪兽的攻击力变成和另1只怪兽的攻击力相同。'),
(47013502, 'Dodger Dragon', '躲避龙', 'アボイド・ドラゴン', 'Effect Monster', 'Dragon', 'WIND', 4, 1900, 1200, '这张卡的召唤不会被无效化。这张卡召唤成功的回合，对方不能把反击陷阱卡发动。'),
(19700943, 'Dododo Bot', '怒怒怒机器人', 'ドドドボット', 'Effect Monster', 'Machine', 'EARTH', 4, 1800, 1900, '这张卡通常召唤的场合，必须里侧守备表示盖放。这张卡攻击的场合，这张卡直到伤害步骤结束时不受这张卡以外的卡的效果影响。'),
(57996334, 'Dododo Buster', '怒怒怒破坏者', 'ドドドバスター', 'Effect Monster', 'Warrior', 'EARTH', 6, 1900, 800, '①：只有对方场上才有怪兽存在的场合，这张卡可以从手卡特殊召唤。这个方法特殊召唤的这张卡的等级变成4星。 ②：这张卡上级召唤成功时，以自己墓地1只「怒怒怒」怪兽为对象才能发动。那只怪兽守备表示特殊召唤。'),
(85310252, 'Dododo Driver', '怒怒怒车夫', 'ドドドドライバー', 'Effect Monster', 'Warrior', 'EARTH', 4, 1800, 200, '这张卡被名字带有「怒怒怒」的怪兽的效果特殊召唤的回合，可以选择自己场上1只名字带有「怒怒怒」的怪兽，从以下效果选择1个发动。这个效果1回合可以使用最多2次。 ●选择的怪兽的等级上升1星。 ●选择的怪兽的等级下降1星。'),
(75421661, 'Dododo Swordsman', '怒怒怒斗笠剑士', 'ドドドガッサー', 'Effect Monster', 'Warrior', 'EARTH', 8, NULL, 3000, '只要反转召唤的这张卡在场上表侧表示存在，这张卡的攻击力上升3500。此外，这张卡反转时，选择场上表侧表示存在的最多2只怪兽才能发动。选择的怪兽破坏。'),
(83274244, 'Dododo Warrior', '怒怒怒战士', 'ドドドウォリアー', 'Effect Monster', 'Warrior', 'EARTH', 6, 2300, 900, '这张卡可以不用解放作召唤。这个方法召唤的这张卡的原本攻击力变成1800。此外，这张卡攻击的场合，直到伤害步骤结束时对方墓地发动的效果无效化。'),
(39432962, 'Dododo Witch', '怒怒怒魔女', 'ドドドウィッチ', 'Effect Monster', 'Warrior', 'EARTH', 4, 1200, 1600, '①：这张卡召唤·特殊召唤成功时才能发动。从手卡把「怒怒怒魔女」以外的1只「怒怒怒」怪兽表侧攻击表示或者里侧守备表示特殊召唤。'),
(62880279, 'Dodododo Warrior', '怒怒怒怒战士', 'ドドドドウォリアー', 'Effect Monster', 'Warrior', 'EARTH', 6, 2300, 900, '这个卡名的①②的效果1回合各能使用1次。 ①：从卡组把1只「怒怒怒」怪兽送去墓地才能发动。这张卡从手卡特殊召唤。这个效果特殊召唤的这张卡的等级变成4星，攻击力变成1800。这个效果的发动后，直到回合结束时自己不是超量怪兽不能从额外卡组特殊召唤。 ②：超量素材的这张卡为让超量怪兽的效果发动而被取除的场合才能发动。从卡组把1只「刷拉拉」怪兽加入手卡。'),
(73866096, 'Dodododraw', '怒怒怒抽牌', 'ドドドドロー', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '把手卡或者自己场上表侧表示存在的1只名字带有「怒怒怒」的怪兽送去墓地才能发动。从卡组抽2张卡。「怒怒怒抽卡」在1回合只能发动1张。'),
(59724555, 'Dodododwarf Gogogoglove', '怒怒怒矮人－隆隆隆手套', 'ドドドドワーフ－GG', 'Effect Monster', 'Rock', 'EARTH', 4, NULL, 1800, '这个卡名的①②的效果1回合各能使用1次。 ①：自己主要阶段才能发动。从手卡把1只「刷拉拉」怪兽或「我我我」怪兽特殊召唤。 ②：这张卡在墓地存在，自己场上有「怒怒怒矮人-隆隆隆手套」以外的，「隆隆隆」怪兽或「怒怒怒」怪兽存在的场合才能发动。这张卡特殊召唤。这个效果特殊召唤的这张卡从场上离开的场合除外。'),
(29491335, 'DOG Fighter Token', '星际仙踪-DOG战斗机', 'Kozmo－ドッグファイター', 'Token', 'Machine', NULL, NULL, NULL, NULL, NULL),
(1003028, 'Doggy Diver', '老虎狗潜水员', 'トラブル・ダイバー', 'Effect Monster', 'Warrior', 'DARK', 4, 1000, 1000, '对方场上有怪兽存在，自己场上表侧表示存在的怪兽只有4星怪兽的场合，这张卡可以从手卡特殊召唤。这个方法的「老虎狗潜水员」的特殊召唤1回合只能有1次。把这张卡作为超量召唤的素材的场合，不是战士族怪兽的超量召唤不能使用。'),
(33296432, 'Dogmatika Adin, the Enlightened', '教导之天启 亚丁', '教導の天啓アディン', 'Effect Monster', 'Spellcaster', 'LIGHT', 4, 1000, 1800, '这个卡名的①③的效果1回合各能使用1次。 ①：从额外卡组特殊召唤的怪兽在场上存在的场合才能发动。这张卡从手卡特殊召唤。 ②：这张卡不会被和从额外卡组特殊召唤的怪兽的战斗破坏。 ③：场上的这张卡被战斗·效果破坏的场合才能发动。从卡组把「教导的天启 阿东」以外的1只「教导」怪兽特殊召唤。'),
(51522296, 'Dogmatika Alba Zoa', '凶教导之天底 阿尔白・佐亚', '凶導の白き天底', 'Ritual Effect Monster', 'Spellcaster', 'LIGHT', 12, 4000, 4000, '「凶导的福音」降临 这张卡不用「教导」卡的效果不能仪式召唤。这个卡名的②的效果1回合只能使用1次。 ①：自己场上的「教导」怪兽不受对方发动的融合·同调·超量·连接怪兽的效果影响。 ②：自己主要阶段才能发动。对方从以下效果把1个适用。 ●自身的额外卡组的卡每有2张，从自身的手卡·额外卡组选1张卡送去墓地。 ●自身场上的融合·同调·超量·连接怪兽全部回到额外卡组。'),
(13694209, 'Dogmatika Ashiyan', '教导之神徒 阿萨辛', '教導の神徒', 'Effect Monster', 'Spellcaster', 'LIGHT', 8, 2000, 1500, '这个卡名的①②③的效果1回合各能使用1次。 ①：融合·同调·超量·连接怪兽被送去自己或者对方的墓地的场合才能发动。这张卡从手卡特殊召唤。 ②：这张卡从手卡特殊召唤的场合，以「教导的神徒」以外的自己墓地1张「教导」卡为对象才能发动。那张卡加入手卡。 ③：对方怪兽的攻击宣言时才能发动。自己场上的全部「教导」怪兽的攻击力上升500。'),
(30394645, 'Dogmatika Chaplain', '教导之死徒', '教導の死徒', 'Effect Monster', 'Spellcaster', 'LIGHT', 8, 2000, 2000, '这个卡名的①②③的效果1回合各能使用1次。 ①：这张卡在手卡存在，从额外卡组特殊召唤的怪兽在场上存在的场合才能发动。这张卡特殊召唤。 ②：这张卡从手卡特殊召唤的场合才能发动。双方各自从自身的额外卡组把1只怪兽送去墓地。 ③：这张卡被送去墓地的场合，以「教导的死徒」以外的自己墓地1张「教导」卡为对象才能发动。那张卡加入手卡。'),
(60303688, 'Dogmatika Ecclesia, the Virtuous', '教导之圣女 艾克利西亚', '教導の聖女エクレシア', 'Effect Monster', 'Spellcaster', 'LIGHT', 4, 1500, 1500, '这个卡名的①②的效果1回合各能使用1次。 ①：从额外卡组特殊召唤的怪兽在场上存在的场合才能发动。这张卡从手卡特殊召唤。 ②：这张卡召唤·特殊召唤的场合才能发动。从卡组把「教导的圣女 艾克莉西娅」以外的1张「教导」卡加入手卡。这个效果的发动后，直到回合结束时自己不能从额外卡组把怪兽特殊召唤。 ③：这张卡不会被和从额外卡组特殊召唤的怪兽的战斗破坏。'),
(29354228, 'Dogmatika Encounter', '教导邂逅', 'ドラグマ・エンカウンター', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：可以从以下效果选择1个发动。 ●从手卡把1只「教导」怪兽或「阿不思的落胤」特殊召唤。 ●从自己墓地选1只「教导」怪兽或「阿不思的落胤」加入手卡或特殊召唤。'),
(69680031, 'Dogmatika Fleurdelis, the Knighted', '教导之骑士 芙露露多丽丝', '教導の騎士フルルドリス', 'Effect Monster', 'Spellcaster', 'LIGHT', 8, 2500, 2500, '这个卡名的①②的效果1回合各能使用1次。 ①：自己·对方的主要阶段，从额外卡组特殊召唤的怪兽在场上存在的场合才能发动。这张卡从手卡特殊召唤。自己场上有其他的「教导」怪兽存在的场合，可以再把场上1只表侧表示怪兽的效果直到回合结束时无效。 ②：自己的「教导」怪兽的攻击宣言时才能发动。自己场上的全部「教导」怪兽的攻击力上升500。'),
(73355772, 'Dogmatika Fleurdelis, the Thunderbolt', '教导之雷霆 芙露露多丽丝', '教導の雷霆フルルドリス', 'Effect Monster', 'Spellcaster', 'LIGHT', 8, 2500, 2500, '这个卡名的①②的效果1回合各能使用1次。 ①：自己·对方的主要阶段，从额外卡组特殊召唤的怪兽在场上存在的场合才能发动。这张卡从手卡特殊召唤。 ②：这张卡从手卡特殊召唤的场合才能发动。从卡组把1张「教导」陷阱卡在自己场上盖放。这个效果盖放的卡只要攻击力2500以上的融合·同调·超量·连接怪兽的其中任意种在对方场上存在，在盖放的回合也能发动。'),
(56588755, 'Dogmatika Genesis', '教导创世', 'ドラグマ・ジェネシス', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：以1只自己或者对方的除外状态的融合·同调·超量·连接怪兽和与那只怪兽相同种类（融合·同调·超量·连接）的对方场上1只效果怪兽为对象才能发动。那只除外状态的怪兽回到额外卡组，那只对方场上的怪兽的效果无效。'),
(95679145, 'Dogmatika Maximus', '教导之大神祇官', '教導の大神祇官', 'Effect Monster', 'Spellcaster', 'LIGHT', 8, 1500, 3000, '这个卡名的①②的效果1回合各能使用1次。 ①：从自己墓地把1只融合·同调·超量·连接怪兽除外才能发动。这张卡从手卡特殊召唤。 ②：自己主要阶段才能发动。从自己的额外卡组把2只卡名不同的怪兽送去墓地。对方从自身的额外卡组把2只怪兽送去墓地。这个效果的发动后，直到回合结束时自己不能从额外卡组把怪兽特殊召唤。'),
(65589010, 'Dogmatika Nation', '教导国家 德拉格马', '教導国家ドラグマ', 'Spell Card', 'Field', NULL, NULL, NULL, NULL, '这个卡名的②③的效果1回合各能使用1次。 ①：只要这张卡在场地区域存在，自己场上的「教导」怪兽不会成为从额外卡组特殊召唤的双方怪兽的效果的对象。 ②：自己的「教导」怪兽和对方怪兽进行战斗的伤害计算后才能发动。那只对方怪兽破坏。 ③：场地区域的表侧表示的这张卡被对方的效果破坏的场合才能发动。双方各自从自身的额外卡组把1只怪兽送去墓地。'),
(22073844, 'Dogmatika Nexus', '教导枢机 尊位德拉格马', '教導枢機テトラドラグマ', 'Effect Monster', 'Spellcaster', 'LIGHT', 11, 3200, 3200, '这张卡不能通常召唤，用这张卡的效果才能特殊召唤。 ①：以自己·对方的墓地的融合·同调·超量·连接怪兽合计4只为对象才能发动。这张卡从手卡特殊召唤，作为对象的怪兽除外。 ②：特殊召唤的怪兽和这张卡进行战斗的伤害步骤开始时发动。对方场上的攻击表示怪兽全部破坏。那之后，给与对方这个效果破坏的融合·同调·超量·连接怪兽数量×800伤害。'),
(82956214, 'Dogmatika Punishment', '教导惩戒', 'ドラグマ・パニッシュメント', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：以对方场上1只表侧表示怪兽为对象才能发动。把持有那只怪兽的攻击力以上的攻击力的1只怪兽从额外卡组送去墓地，作为对象的怪兽破坏。这张卡的发动后，直到下次的自己回合的结束时自己不能从额外卡组把怪兽特殊召唤。'),
(96891787, 'Dogmatika Theo, the Iron Punch', '教导之铁槌 提奥', '教導の鉄槌テオ', 'Effect Monster', 'Spellcaster', 'LIGHT', 4, 1800, 1500, '这个卡名的①③的效果1回合各能使用1次。 ①：从额外卡组特殊召唤的怪兽在场上存在的场合才能发动。这张卡从手卡特殊召唤。 ②：这张卡不会被和从额外卡组特殊召唤的怪兽的战斗破坏。 ③：以从额外卡组特殊召唤的场上1只表侧表示怪兽为对象才能发动。直到回合结束时，这张卡的攻击力上升600，作为对象的怪兽的攻击力下降600。'),
(87481592, 'Dogmatikacism', '教导神理', '教導神理', 'Spell Card', 'Equip', NULL, NULL, NULL, NULL, '这个卡名的②的效果1回合只能使用1次。 ①：装备怪兽的攻击力在装备怪兽是「教导」怪兽的场合攻击力上升自身的等级×100，那以外的场合下降自己场上的「教导」怪兽数量×200。 ②：装备怪兽被破坏让这张卡被送去墓地的场合才能发动。从额外卡组把1只怪兽送去墓地。'),
(31002402, 'Dogmatikalamity', '凶教导之福音', '凶導の福音', 'Spell Card', 'Ritual', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：等级合计直到变成和仪式召唤的怪兽相同为止的自己的手卡·场上的怪兽解放或者和仪式召唤的怪兽相同等级的1只怪兽从额外卡组送去墓地，从手卡把1只「教导」仪式怪兽仪式召唤。这张卡的发动后，直到回合结束时自己不能从额外卡组把怪兽特殊召唤。'),
(93053159, 'Dogmatikalamity Alba System', '白教导枢机龙', '白の枢機竜', 'Fusion Monster', 'Dragon', 'DARK', 8, 4500, 2500, '「阿不思的落胤」＋自己墓地的卡名不同的怪兽×6 这张卡用融合召唤才能从额外卡组特殊召唤。 ①：这张卡可以向对方怪兽全部各作1次攻击。 ②：这张卡的攻击宣言之际，自己必须把额外卡组1张卡送去墓地。 ③：1回合1次，融合召唤的这张卡在怪兽区域存在，需以「阿不思的落胤」为融合素材的融合怪兽在自己墓地有6种类以上存在的场合才能发动。双方的额外卡组的卡全部送去墓地。'),
(60921537, 'Dogmatikamacabre', '凶教导之葬列', '凶導の葬列', 'Spell Card', 'Ritual', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：等级合计直到变成仪式召唤的怪兽的等级以上为止，把自己的手卡·场上的怪兽解放或者作为解放的代替而把自己墓地的融合·同调怪兽除外，从自己的手卡·墓地把1只「教导」仪式怪兽仪式召唤。那之后，场上有「凶导的白骑士」以及「凶导的白圣骸」存在的场合，可以把自己或者对方的额外卡组确认，那之内的1只怪兽送去墓地。'),
(35569555, 'Dogmatikamatrix', '凶教导之圣告', '凶導の聖告', 'Spell Card', 'Continuous', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：作为这张卡的发动时的效果处理，以下效果可以适用。 ●从卡组把1只「教导」仪式怪兽或者1张「教导」仪式魔法卡加入手卡。对方场上有怪兽存在的场合，可以再从卡组把1张「教导」卡加入手卡。 ②：1回合1次，自己场上有「教导」仪式怪兽存在的场合才能发动。把自己或者对方的额外卡组确认，那之内的1只怪兽送去墓地。'),
(42158279, 'Dogmatikaturgy', '教导拟剧', 'ドラグマトゥルギー', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的①②的效果1回合只能有1次使用其中任意1个。 ①：等级合计直到变成和仪式召唤的怪兽相同为止，把自己场上的「教导」怪兽或者仪式·融合·同调怪兽解放，从手卡·卡组把1只「教导」仪式怪兽仪式召唤。 ②：把墓地的这张卡除外，以等级不同的自己墓地2只「教导」怪兽为对象才能发动。那2只之内的1只加入手卡，另1只回到卡组最下面。'),
(93332803, 'Dogoran, the Mad Flame Kaiju', '怒焰坏兽 哥吉龙', '怒炎壊獣ドゴラン', 'Effect Monster', 'Dinosaur', 'FIRE', 8, 3000, 1200, '①：这张卡可以把对方场上1只怪兽解放，从手卡往对方场上攻击表示特殊召唤。 ②：对方场上有「坏兽」怪兽存在的场合，这张卡可以从手卡攻击表示特殊召唤。 ③：「坏兽」怪兽在自己场上只能有1只表侧表示存在。 ④：1回合1次，把自己·对方场上3个坏兽指示物取除才能发动（这个效果发动的回合，这张卡不能攻击）。对方场上的怪兽全部破坏。'),
(95816395, 'Dogu', '土偶', 'どぐう', 'Effect Monster', 'Rock', 'EARTH', 4, 1900, NULL, '「土偶」的效果1回合只能使用1次。 ①：这张卡被对方的效果送去墓地的回合的结束阶段才能发动。不在自己的场上·墓地存在的等级的1只怪兽从卡组加入手卡。'),
(42021064, 'Dogurad, the Stonetrooper', '机动石器 土偶罗多', '機動石器ドグラード', 'Link Monster', 'Rock', 'EARTH', NULL, 1000, NULL, '包含岩石族怪兽的怪兽2只以上 这个卡名的①②的效果1回合各能使用1次。 ①：这张卡特殊召唤的场合，以自己墓地1只岩石族怪兽为对象才能发动。这张卡的攻击力上升作为对象的怪兽的攻击力数值。 ②：对方主要阶段，以持有这张卡的攻击力以下的攻击力的场上1只其他怪兽为对象才能发动。这张卡的攻击力下降作为对象的怪兽的攻击力数值，作为对象的怪兽破坏。'),
(57062206, 'Doitsu', '何者', 'ドイツ', 'Union Effect Monster', 'Fairy', 'EARTH', 4, 100, 200, '1回合只有1次在自己的主要阶段可以当作装备卡使用给自己的「他者」装备，或者把装备解除以表侧攻击表示特殊召唤。只在这个效果当作装备卡使用时，装备怪兽的攻击力上升2500点。（1只怪兽可以装备的同盟最多1张。装备怪兽被战斗破坏的场合，作为代替把这张卡破坏。）'),
(42143067, 'Doki Doki', '怒气土器', '怒気土器', 'Effect Monster', 'Rock', 'EARTH', 2, 500, 500, '这个卡名的效果1回合只能使用1次。 ①：从手卡丢弃1只岩石族怪兽才能发动。原本的属性·等级和那只怪兽相同的1只岩石族怪兽从卡组表侧攻击表示或者里侧守备表示特殊召唤。'),
(25882881, 'Dokuroizo the Grim Reaper', '死神骷髅', '死神のドクロイゾ', 'Normal Monster', 'Zombie', 'DARK', 3, 900, 1200, '使用地狱一击夺取灵魂的死神。'),
(99721536, 'Dokurorider', '骷髅骑手', 'スカルライダー', 'Ritual Monster', 'Zombie', 'DARK', 6, 1900, 1850, '使用「骷髅骑手的复活」特殊召唤。'),
(30325729, 'Dokuroyaiba', '死神回旋镖', '死神ブーメラン', 'Normal Monster', 'Fiend', 'FIRE', 3, 1000, 400, '确定目标后，无论敌人逃到哪里都会追脑瓜，带有意识的回旋镖。'),
(71595845, 'Doll Happiness', '人偶的幸福', '人形の幸福', 'Spell Card', 'Continuous', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：作为这张卡的发动时的效果处理，从卡组把1只「德梅特爷爷」或者「玩具盒」加入手卡。 ②：只要自己场上有「珂珑公主」存在，对方不能选择攻击力或守备力是0的怪兽作为攻击对象。 ③：1回合1次，可以发动。选自己的手卡·场上1只怪兽破坏，从卡组把1张「人偶怪兽」卡送去墓地。这个回合，自己不是超量怪兽不能从额外卡组特殊召唤。'),
(67331360, 'Doll House', '人偶之家', '人形の家', 'Spell Card', 'Field', NULL, NULL, NULL, NULL, '这个卡名的①的效果1回合只能使用1次。 ①：以自己墓地1只攻击力或守备力是0的通常怪兽为对象才能发动。那1只同名怪兽从卡组作为暗属性·6星怪兽特殊召唤。自己场上有「珂珑公主」存在的场合，这个效果的对象可以变成2只。 ②：对方怪兽的攻击宣言时才能发动。选自己场上1只「德梅特爷爷」作为自己场上的「珂珑公主」的超量素材。那之后，战斗阶段结束。'),
(18106132, 'Doll Monster Bear-Bear', '人偶怪兽 熊仔', 'ドール・モンスター 熊っち', 'Normal Monster', 'Beast', 'WIND', 4, NULL, NULL, '就算我们受了伤要坏掉也不要紧。 德梅特爷爷会修好我们的！'),
(72717433, 'Doll Monster Miss Mädchen', '人偶怪兽 小姑娘', 'ドール・モンスター ガールちゃん', 'Normal Monster', 'Fairy', 'LIGHT', 4, NULL, NULL, '欢迎来到我们的家！ 珂珑小公主和德梅特爷爷还有许多其他人偶都一块生活在这儿！'),
(16972957, 'Doma The Angel of Silence', '死之沉默天使 多玛', '死の沈黙の天使 ドマ', 'Normal Monster', 'Fairy', 'DARK', 5, 1600, 1400, '司职死亡的天使，若被这家伙盯上，难逃一死。'),
(84171830, 'Domain of the True Monarchs', '真帝王领域', '真帝王領域', 'Spell Card', 'Field', NULL, NULL, NULL, NULL, '①：只要自己的额外卡组没有卡存在并是只有自己场上才有上级召唤的怪兽存在，对方不能从额外卡组把怪兽特殊召唤。 ②：自己的上级召唤的怪兽的攻击力只在向对方怪兽攻击的伤害计算时上升800。 ③：1回合1次，自己主要阶段才能发动。自己手卡1只攻击力2800/守备力1000的怪兽的等级直到回合结束时下降2星。'),
(32663969, 'Domino Effect', '多米诺', 'ドミノ', 'Spell Card', 'Continuous', NULL, NULL, NULL, NULL, '对方场上存在的怪兽被战斗破坏送去墓地时，可以把自己场上存在的1只怪兽送去墓地，对方场上存在的1只怪兽破坏。'),
(40366667, 'Dominus Impulse', '灵主王之波动', '霊王の波動', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。对方场上有卡存在的场合，这张卡的发动从手卡也能用。 ①：包含把怪兽特殊召唤效果的魔法·陷阱·怪兽的效果发动时才能发动。那个效果无效。自己墓地有陷阱卡存在的场合，再把那张无效的卡破坏。这张卡从手卡发动的场合，发动后，这次决斗中自己不能把光·地·风属性怪兽的效果发动。'),
(97045737, 'Dominus Purge', '圣主王之粉碎', '聖王の粉砕', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。对方场上有卡存在的场合，这张卡的发动从手卡也能用。 ①：包含从卡组把卡加入手卡效果的魔法·陷阱·怪兽的效果发动时才能发动。那个效果无效。自己墓地有陷阱卡存在的场合，再把那张无效的卡破坏。这张卡从手卡发动的场合，发动后，这次决斗中自己不能把暗·水·炎属性怪兽的效果发动。'),
(6325660, 'Dominus Spark', NULL, NULL, 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, NULL),
(42091632, 'Dominus Spiral', '命主王之螺旋', '命王の螺旋', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。对方把手卡·墓地的怪兽的效果发动的回合，这张卡的发动从手卡也能用。 ①：以对方场上1只怪兽为对象才能发动。那只怪兽回到手卡·额外卡组。自己墓地没有陷阱卡存在的场合，再让对方可以从自身墓地把1只怪兽特殊召唤。这张卡从手卡发动的场合，发动后，这次决斗中自己不能把光·暗属性怪兽的效果发动。'),
(93238626, 'Don Thousand''s Throne', '上千主上的玉座', 'ドン・サウザンドの玉座', 'Spell Card', 'Continuous', NULL, NULL, NULL, NULL, '对方的结束阶段时，自己回复那个回合受到战斗伤害的次数×500基本分。此外，自己场上的名字带有「混沌No.」以外的「No.」的怪兽成为攻击对象时，可以通过把这张卡送去墓地让那次攻击无效。那之后，把持有和那只自己怪兽相同「No.」数字的名字带有「混沌No.」的怪兽在那只怪兽上面重叠当作超量召唤从额外卡组特殊召唤。「上千主上的玉座」在自己场上只能有1张表侧表示存在。'),
(3493978, 'Don Turtle', '首领龟', '首領亀', 'Effect Monster', 'Reptile', 'WATER', 3, 1100, 1200, '这张卡召唤·反转召唤成功时，可以从自己的手卡特殊召唤任意数量的「首领龟」上场。'),
(76922029, 'Don Zaloog', '首领 扎鲁格', '首領・ザルーグ', 'Effect Monster', 'Warrior', 'DARK', 4, 1400, 1500, '这张卡给与对方玩家战斗伤害时，可以选择下面1个效果发动： ●对方随机丢弃1张手卡。 ●对方的卡组最上面的2张卡送去墓地。'),
(65938950, 'Don''t Slip, the Dogs of War', '纲引犬会', '綱引犬会', 'Spell Card', 'Field', NULL, NULL, NULL, NULL, '①：双方玩家在自身的抽卡阶段通常抽卡时，那是调整的场合，把那张卡给对方观看才能发动。把这个效果发动的玩家从卡组抽2张。 ②：这张卡的①的效果让对方抽卡的场合发动。自己失去2000基本分，这张卡送去墓地。'),
(8728498, 'Donner, Dagger Fur Hire', '空牙团的怀剑 多娜', '空牙団の懐剣 ドナ', 'Link Monster', 'Beast-Warrior', 'EARTH', NULL, 1600, NULL, '种族不同的怪兽2只 这个卡名的①②的效果1回合只能有1次使用其中任意1个。 ①：以自己场上1只「空牙团」怪兽和对方场上1只怪兽为对象才能发动。那些怪兽破坏。 ②：把自己场上1只怪兽解放才能发动。原本卡名和解放的怪兽不同的1只「空牙团」怪兽从自己的手卡·墓地特殊召唤。把连接怪兽解放发动的场合，可以再让另1只特殊召唤。'),
(94073244, 'Donpa, Marksman Fur Hire', '空牙团的击手 东帕', '空牙団の撃手 ドンパ', 'Effect Monster', 'Beast', 'WIND', 2, 500, 1000, '这个卡名的①②的效果1回合各能使用1次。 ①：自己主要阶段才能发动。从手卡把「空牙团的击手 砰帕」以外的1只「空牙团」怪兽特殊召唤。 ②：这张卡在怪兽区域存在的状态，自己场上有「空牙团」怪兽特殊召唤的场合，以场上1张表侧表示卡为对象才能发动。那张卡破坏。'),
(14146794, 'Donyoribo @Ignister', '阴郁里波＠伊格尼斯者', 'ドンヨリボー＠イグニスター', 'Effect Monster', 'Cyberse', 'DARK', 1, 300, NULL, '这个卡名的①②的效果1回合各能使用1次。 ①：自己的「@火灵天星」怪兽被攻击的伤害计算时把这张卡从手卡丢弃才能发动。那次战斗发生的对自己的战斗伤害变成0。 ②：「@火灵天星」怪兽或者「“艾”」魔法·陷阱卡的给与对方伤害的效果发动时，把墓地的这张卡除外才能发动（伤害步骤也能发动）。那个效果给与对方的伤害变成2倍。'),
(31230289, 'Doodle Beast - Stego', '涂yā兽－jiàn龙', 'らくがきじゅう－すてご', 'Effect Monster', 'Dinosaur', 'EARTH', 5, 1200, 1800, '这个卡名的①②的效果1回合各能使用1次。 ①：自己场上的怪兽不存在的场合或者只有恐龙族怪兽的场合才能发动。这张卡从手卡特殊召唤。 ②：这张卡召唤·特殊召唤成功的场合才能发动。从卡组把1张「涂鸦本」魔法·陷阱卡加入手卡。那之后，选自己1张手卡丢弃。'),
(67725394, 'Doodle Beast - Tyranno', '涂yā兽－bào龙', 'らくがきじゅう－てらの', 'Effect Monster', 'Dinosaur', 'EARTH', 8, 2400, 1200, '这张卡可以把1只恐龙族怪兽解放作上级召唤。这个卡名的①的效果1回合只能使用1次。 ①：场上有恐龙族怪兽存在的场合，自己·对方的主要阶段才能发动。手卡的这张卡上级召唤。 ②：这张卡召唤成功的场合才能发动。选场上1只怪兽破坏。这张卡把「涂鸦兽」怪兽解放作上级召唤的场合，再让这张卡的攻击力上升破坏的怪兽的攻击力一半数值。'),
(94113093, 'Doodlebook - Uh uh uh!', '涂yā本－此路不tōng', 'らくがきちょう－とおせんぼ', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的①②的效果1回合各能使用1次。 ①：自己的恐龙族怪兽被选择作为攻击对象时才能发动。那次攻击无效。那之后，可以从自己墓地选1只「涂鸦兽」怪兽特殊召唤。这个效果特殊召唤的怪兽不会被战斗破坏，结束阶段破坏。 ②：把墓地的这张卡除外才能发动。从卡组把1只5星以上的恐龙族怪兽加入手卡。这个效果在这张卡送去墓地的回合不能发动。'),
(10389794, 'Doom Donuts', '死亡甜甜圈', 'デス・ドーナツ', 'Flip Effect Monster', 'Fiend', 'DARK', 1, NULL, NULL, '反转：场上表侧表示存在的原本攻击力或者原本守备力是0的怪兽全部破坏。'),
(76039636, 'Doom Dozer', '魔鬼铲土虫', 'デビルドーザー', 'Effect Monster', 'Insect', 'EARTH', 8, 2800, 2600, '这张卡不能通常召唤。把自己墓地2只昆虫族怪兽从游戏中除外的场合才能特殊召唤。这张卡给与对方基本分战斗伤害时，从对方卡组最上面把1张卡送去墓地。'),
(69436288, 'Doom Kraken', '死亡乌贼', 'デス・クラーケン', 'Effect Monster', 'Aqua', 'WATER', 4, 1400, 1600, '这个卡名的①②的效果1回合各能使用1次。 ①：场上有「海」存在的场合，以「死亡乌贼」以外的自己场上1只水属性怪兽和对方场上1只怪兽为对象才能发动。这张卡从手卡特殊召唤，作为对象的自己怪兽回到持有者手卡，作为对象的对方怪兽破坏。这个效果在对方回合也能发动。 ②：对方怪兽的攻击宣言时才能发动。这张卡回到持有者手卡，那次攻击无效。'),
(78744660, 'Doom Regina Archfiend', NULL, NULL, 'Pendulum Effect Ritual Monster', 'Fiend', 'LIGHT', 7, 2100, 2900, NULL),
(94944637, 'Doom Shaman', '魔族召唤师', '魔族召喚師', 'Gemini Monster', 'Spellcaster', 'DARK', 6, 2400, 2000, '这张卡在墓地或者场上表侧表示存在的场合，当作通常怪兽使用。场上表侧表示存在的这张卡可以作当通常召唤使用的再度召唤，这张卡当作效果怪兽使用并得到以下效果。 ●把手卡或者墓地存在的1只恶魔族怪兽特殊召唤。这个效果1回合只能使用1次。这张卡从场上离开时，这个效果特殊召唤的恶魔族怪兽破坏。'),
(22804644, 'Doom Virus Dragon', '死亡病毒龙', 'デス・ウイルス・ドラゴン', 'Fusion Monster', 'Dragon', 'DARK', 4, 1900, 1500, '这张卡在用「克里底亚之牙」的效果把自己的手卡·场上的「死之卡组破坏病毒」送去墓地的场合才能特殊召唤。 ①：这张卡特殊召唤成功的场合发动。对方场上的怪兽，对方手卡，用对方回合计算的3回合内对方抽到的卡全部确认，那之内的攻击力1500以上的怪兽全部破坏。'),
(83116692, 'Doombearer Psychopompos', '死眼之传灵-普绪科蓬波斯', '死眼の伝霊－プシュコポンポス', 'Tuner Monster', 'Zombie', 'EARTH', 2, NULL, NULL, '这个卡名的①②的效果1回合各能使用1次。 ①：这张卡特殊召唤成功的场合发动。对方墓地的以下的卡之内数量较多方的效果适用。 ●怪兽卡：这张卡除外，对方从自身墓地选1只怪兽除外。 ●魔法·陷阱卡：这张卡送去墓地，对方选自身场上1只怪兽送去墓地。 ②：这张卡被除外的场合，下个回合的结束阶段才能发动。除外的这张卡特殊召唤。'),
(78700060, 'Doomcaliber Knight', '死灵骑士', '死霊騎士デスカリバー・ナイト', 'Effect Monster', 'Fiend', 'DARK', 4, 1900, 1800, '这张卡不能特殊召唤。 ①：怪兽的效果发动时，把这张卡解放发动。那个发动无效并破坏。'),
(58616392, 'Doomdog Octhros', '魔犬 俄八托洛斯', '魔犬オクトロス', 'Effect Monster', 'Fiend', 'DARK', 3, 800, 800, '这个卡名的效果1回合只能使用1次。 ①：这张卡从场上送去墓地的场合发动。从卡组把1只恶魔族·8星怪兽加入手卡。'),
(6021033, 'Doomkaiser Dragon', '死亡凯萨龙', 'デスカイザー・ドラゴン', 'Synchro Monster', 'Zombie', 'FIRE', 6, 2400, 1500, '「僵尸带菌者」＋调整以外的不死族怪兽1只以上 ①：这张卡特殊召唤成功时，以对方墓地1只不死族怪兽为对象才能发动。那只不死族怪兽在自己场上攻击表示特殊召唤。这张卡从场上离开时那只怪兽破坏。'),
(1764972, 'Doomkaiser Dragon/Assault Mode', '死亡凯萨龙／爆裂', 'デスカイザー・ドラゴン／バスター', 'Effect Monster', 'Zombie', 'FIRE', 8, 2900, 2000, '这张卡不能通常召唤。「爆裂模式」的效果才能特殊召唤。这张卡特殊召唤成功时，从自己·对方的墓地选择不死族怪兽任意数量在自己场上特殊召唤。这个效果特殊召唤的怪兽的效果无效化，这个回合的结束阶段时破坏。此外，场上的这张卡被破坏时，可以选择自己墓地1只「死亡帝王龙」特殊召唤。'),
(39185163, 'Doomking Balerdroch', '死灵王 堕哈司拉', '死霊王 ドーハスーラ', 'Effect Monster', 'Zombie', 'DARK', 8, 2800, 2000, '这个卡名的②的效果1回合只能使用1次。 ①：「死灵王 恶眼」以外的不死族怪兽的效果发动时才能发动（同一连锁上最多1次）。从以下效果让1个适用。这个回合，自己的「死灵王 恶眼」的效果不能有相同效果适用。 ●那个效果无效。 ●自己或对方的场上·墓地1只怪兽除外。 ②：场地区域有表侧表示卡存在的场合，自己·对方的准备阶段才能发动。这张卡从墓地守备表示特殊召唤。'),
(64379430, 'Doomsday Horror', '终焉之精灵', '終焉の精霊', 'Effect Monster', 'Fiend', 'DARK', 4, -1, -1, '这张卡的攻击力·守备力变成从游戏中除外的暗属性怪兽数量×300的数值。这张卡被破坏送去墓地时，从游戏中除外的暗属性怪兽全部回到墓地。'),
(46173680, 'Doomsday Token', '终焉之焰', '終焉の焔', 'Token', 'Fiend', NULL, NULL, NULL, NULL, NULL),
(58369990, 'Doomstar Magician', '凶星之魔术师', '凶星の魔術師', 'Effect Monster', 'Spellcaster', 'DARK', 4, 1800, 300, '①：1回合1次，丢弃1张手卡，以自己或者对方的灵摆区域1张卡为对象才能发动。那张卡破坏，自己从卡组抽1张。'),
(49109013, 'Doomstar Ulka', '魔星忧流迦', '魔星のウルカ', 'Effect Monster', 'Beast', 'WIND', 4, 1500, 400, '这个卡名的①②的效果1回合各能使用1次。 ①：只让自己场上的怪兽1只因对方的效果从场上离开时，把手卡·墓地的这张卡除外才能发动。那只怪兽在墓地存在的场合或者是表侧除外状态的场合，那只怪兽特殊召唤。那以外的场合，除外状态的这张卡特殊召唤。 ②：这张卡特殊召唤的场合才能发动。这张卡的攻击力直到下个回合的结束时上升1500。'),
(31010081, 'DoomZ Break - Diactorus', '终刻狱徒 迪亚克特罗斯', '終刻獄徒 ディアクトロス', 'XYZ Monster', 'Machine', 'WIND', 4, 2400, NULL, '4星怪兽×2 这个卡名的①②的效果1回合各能使用1次。 ①：这张卡特殊召唤的场合才能发动。自己的手卡·场上（表侧表示）1张「终刻」卡破坏。那之后，可以把场上1只怪兽破坏。 ②：有「终刻」怪兽或「无垢者 米底乌斯」在作为超量素材中的这张卡被效果破坏的场合才能发动。从卡组选1张装备魔法卡加入手卡或送去墓地。'),
(38007649, 'DoomZ Change', '终刻变转', '終刻変転', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的①②的效果1回合各能使用1次。 ①：「终刻转变」以外的自己的手卡·卡组·场上（表侧表示）1张「终刻」卡破坏。 ②：这张卡被效果破坏的场合才能发动。从自己墓地把「终刻转变」以外的1张「终刻」卡加入手卡。那之后，可以从手卡把1只「终刻」怪兽特殊召唤。'),
(84054556, 'DoomZ Command "A.D.R.A.S.T.E.I.A."', NULL, NULL, 'Spell Card', 'Equip', NULL, NULL, NULL, NULL, NULL),
(68831625, 'DoomZ Command "D.O.O.M.D.U.R.G."', '终刻起动《D.O.O.M.D.U.R.G.》', '終刻起動『D.O.O.M.D.U.R.G.』', 'Spell Card', 'Equip', NULL, NULL, NULL, NULL, '①：自己·对方的准备阶段发动。给与装备怪兽的控制者500伤害。 ②：有这张卡装备的「终刻」怪兽或者有这张卡在作为超量素材中的机械族·风属性超量怪兽得到以下效果。 ●对方不能把这张卡作为效果的对象。 ●自己·对方回合1次，可以发动。自己场上1张其他的表侧表示卡破坏。这张卡在这个回合攻击力上升这张卡的等级·阶级×100，可以直接攻击，进行战斗的伤害步骤结束时破坏。'),
(80320877, 'DoomZ Destruction', '终刻决坏', '終刻決壊', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的①②的效果1回合各能使用1次。 ①：以自己场上1只「终刻」超量怪兽为对象才能把这张卡发动。这张卡当作持有以下效果的装备卡使用给那只怪兽装备。 ●对方不能用抽卡以外的方法从卡组把卡加入手卡。 ②：这张卡被效果破坏的场合，以场上1只表侧表示怪兽为对象才能发动。从卡组把1只「终刻」怪兽当作装备魔法卡使用给作为对象的怪兽装备。'),
(32442017, 'DoomZ Raiders', '终刻击针', '終刻撃針', 'Spell Card', 'Continuous', NULL, NULL, NULL, NULL, '这个卡名的①②的效果1回合只能有1次使用其中任意1个。 ①：自己主要阶段才能发动。自己的手卡·场上（表侧表示）1张其他的「终刻」卡破坏。那之后，从卡组选1只「终刻」怪兽加入手卡或特殊召唤。这个效果的发动后，直到回合结束时自己不是超量怪兽不能从额外卡组特殊召唤。 ②：这张卡被效果破坏的场合，以场上1只表侧表示怪兽为对象才能发动。那只怪兽破坏。'),
(28877382, 'DoomZ V Five - Amalthe', '终刻龙机Ⅴ－阿玛耳忒', '終刻竜機Ⅴ－アマルテ', 'Effect Monster', 'Dragon', 'DARK', 4, 1600, 1200, '这个卡名的①②的效果1回合各能使用1次。 ①：这张卡召唤·特殊召唤的场合或者被效果破坏的场合才能发动。从卡组把「终刻龙机5-阿玛尔忒」以外的1只「终刻」怪兽加入手卡。 ②：自己·对方回合，这张卡有装备卡装备的场合才能发动。把持有和这张卡的等级相同数值的阶级的1只机械族·风属性超量怪兽当作超量召唤从额外卡组特殊召唤，把这张卡以及这张卡的装备卡全部作为那超量素材。'),
(54265980, 'DoomZ VII Seven - Elara', '终刻龙机Ⅶ－伊拉拉', '終刻竜機Ⅶ－エララ', 'Effect Monster', 'Dragon', 'DARK', 4, 1400, 1200, '这个卡名的①②的效果1回合各能使用1次。 ①：这张卡召唤·特殊召唤的场合或者被效果破坏的场合才能发动。从卡组把1张「终刻」魔法·陷阱卡在自己场上盖放。 ②：自己·对方回合，这张卡有装备卡装备的场合才能发动。把持有和这张卡的等级相同数值的阶级的1只机械族·风属性超量怪兽当作超量召唤从额外卡组特殊召唤，把这张卡以及这张卡的装备卡全部作为那超量素材。'),
(95626382, 'DoomZ XII End - Drastrius', '终刻狱龙机ⅩⅡ－德拉斯特琉斯', '終獄龍機ⅩⅡ－ドラストリウス', 'XYZ Monster', 'Machine', 'WIND', 8, 2700, 1500, '8星怪兽×3 这个卡名的①③的效果1回合各能使用1次。 ①：这张卡超量召唤的场合才能发动。场上1只其他的表侧表示怪兽当作装备魔法卡使用给这张卡装备。 ②：这张卡1回合只有1次不会被战斗·效果破坏。 ③：对方把场上·墓地的怪兽的效果发动时，把这张卡1个超量素材取除才能发动。那个效果无效。那之后，可以把对方场上1只表侧表示怪兽当作装备魔法卡使用给这张卡装备。'),
(92472273, 'DoomZ XII Zero - Drastea', '终刻龙机ⅩⅡ－德拉斯提亚', '終刻竜機ⅩⅡ－ドラスティア', 'Effect Monster', 'Dragon', 'DARK', 8, 2400, 1500, '这个卡名的①②的效果1回合各能使用1次。 ①：以自己场上1张「终刻」卡为对象才能发动。那张卡破坏，这张卡从手卡特殊召唤。那之后，可以从卡组把1张装备魔法卡给这张卡装备。 ②：自己·对方回合，这张卡有装备卡装备的场合才能发动。把持有和这张卡的等级相同数值的阶级的1只机械族·风属性超量怪兽当作超量召唤从额外卡组特殊召唤，把这张卡以及这张卡的装备卡全部作为那超量素材。'),
(65848113, 'DoomZ XIII Over - Graflario', NULL, NULL, 'XYZ Monster', 'Machine', 'WIND', 5, 2400, 1500, NULL),
(53855410, 'Doppel Token', '二重身战士', 'ドッペル・ウォリアー', 'Token', 'Warrior', NULL, NULL, NULL, NULL, NULL),
(66395299, 'Doppelganger', '二重身回击', 'ドッペル・ゲイナー', 'Trap Card', 'Continuous', NULL, NULL, NULL, NULL, '因对方场上存在的怪兽的效果受到伤害时，给与对方基本分和受到的伤害相同的伤害。'),
(53855409, 'Doppelwarrior', '二重身战士', 'ドッペル・ウォリアー', 'Effect Monster', 'Warrior', 'DARK', 2, 800, 800, '①：从自己墓地有怪兽特殊召唤时才能发动。这张卡从手卡特殊召唤。 ②：这张卡作为同调素材送去墓地的场合才能发动。在自己场上把2只「二重身衍生物」（战士族·暗·1星·攻/守400）攻击表示特殊召唤。'),
(11590299, 'Dora Dora', '哆啦哆啦', 'ドラ・ドラ', 'Effect Monster', 'Dragon', 'FIRE', 3, 400, 200, '这个卡名的①的效果1回合只能使用1次。 ①：这张卡召唤的场合才能发动。从卡组把1只4星以下的龙族·炎属性怪兽加入手卡。 ②：1回合1次，自己主要阶段才能发动。自己卡组最上面的卡翻开。翻开的卡是龙族·炎属性怪兽的场合，那只怪兽送去墓地，这张卡的攻击力上升自己场上的「龙宝龙」数量×1000。不是的场合，翻开的卡回到卡组最下面。'),
(67464807, 'Dora of Fate', '命运之宝牌', '運命のドラ', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '这张卡只能在对方回合发动。选择对方场上1只以表侧表示存在的怪兽。下一个自己的回合，若自己成功召唤出比被选择的怪兽低1颗星的怪兽，则召唤成功时对对方造成被选择的怪兽等级×500点伤害。'),
(84916669, 'Doriado', '多里雅德', 'ドリアード', 'Normal Monster', 'Spellcaster', 'EARTH', 4, 1200, 1400, '森之精灵。借助草木之力来封住对手的行动。'),
(23965037, 'Doriado''s Blessing', '树精的祈祷', 'ドリアードの祈り', 'Spell Card', 'Ritual', NULL, NULL, NULL, NULL, '「精灵术师 树精」降临必要。必须把场上·手卡合计3星以上的卡作为祭品。'),
(756652, 'Doron', '多隆', 'ドローン', 'Normal Monster', 'Warrior', 'EARTH', 2, 900, 500, '分身夹击的怪兽，要小心！'),
(24194033, 'Dorover', '泥浆兽', 'ドローバ', 'Normal Monster', 'Aqua', 'WATER', 3, 900, 800, '粘呼呼的令人感到恶心的怪兽。吐出剧毒的瓦斯进行攻击。'),
(78751195, 'Doshin @Ignister', '沉咚咚＠伊格尼斯者', 'ドシン＠イグニスター', 'Effect Monster', 'Cyberse', 'EARTH', 1, 100, 800, '这个卡名的①②的效果1回合各能使用1次。 ①：自己场上有「@火灵天星」怪兽存在的场合才能发动。这张卡从手卡特殊召唤。 ②：以自己墓地1只电子界族连接怪兽为对象才能发动。那只怪兽回到额外卡组，从卡组把1张「“艾”慕融合」加入手卡。'),
(80776622, 'DoSolfachord Coolia', '哆音服和弦・克理娅', 'ドドレミコード・クーリア', 'Pendulum Effect Monster', 'Fairy', 'WIND', 8, 2700, 2500, '这个卡名的②③的怪兽效果1回合各能使用1次。 ①：这张卡可以把自己场上2只灵摆怪兽解放从手卡特殊召唤。 ②：以对方场上1张表侧表示卡为对象才能发动（自己的灵摆区域有奇数的灵摆刻度存在的场合，这个效果的对象可以变成2张）。那张卡的效果直到对方回合结束时无效。 ③：持有自己的灵摆区域的最高灵摆刻度×300以下的攻击力的场上的怪兽的效果发动时才能发动。那只怪兽破坏。'),
(55226153, 'DoSolfachord Cutia', '哆音服和弦・秋迪娅', 'ドドレミコード・キューティア', 'Pendulum Effect Monster', 'Fairy', 'EARTH', 1, 100, 400, '这个卡名的①的怪兽效果1回合只能使用1次。 ①：这张卡召唤·特殊召唤的场合才能发动。从卡组把「多之七音服·丘蒂娅」以外的1只「七音服」灵摆怪兽加入手卡。 ②：只要自己的灵摆区域有偶数的灵摆刻度存在，自己场上的「七音服」灵摆怪兽的攻击力上升自身的灵摆刻度×100。'),
(82050203, 'Dotedotengu', '走溜溜天狗', 'ドテドテング', 'Effect Monster', 'Fiend', 'WIND', 3, NULL, 800, '这张卡被对方的卡的效果送去墓地的场合，选择对方场上1张卡才能发动。选择的卡回到持有者手卡。'),
(18789533, 'Dotscaper', '点画替罪者', 'ドットスケーパー', 'Effect Monster', 'Cyberse', 'EARTH', 1, NULL, 2100, '这个卡名的①②的效果1回合只能有1次使用其中任意1个，决斗中各能使用1次。 ①：这张卡被送去墓地的场合才能发动。这张卡特殊召唤。 ②：这张卡被除外的场合才能发动。这张卡特殊召唤。'),
(34187685, 'Double Attack', '二重攻击', 'ダブルアタック', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '从手卡丢弃1张怪兽卡去墓地。选择自己场上1只比丢弃怪兽等级低的怪兽。选择的那只怪兽在这个回合可以攻击2次。'),
(60176682, 'Double Attack! Wind and Thunder!!', '魔风冲击波', '魔風衝撃波', 'Spell Card', 'Quick-Play', NULL, NULL, NULL, NULL, '这个卡名的②的效果1回合只能使用1次。 ①：自己场上有「门之守护神」怪兽存在的场合，以场上1张卡为对象才能发动。那张卡破坏。 ②：自己主要阶段把墓地的这张卡除外才能发动。自己的卡组·除外状态的「雷魔神-桑迦」「风魔神-修迦」「水魔神-斯迦」的其中1只加入手卡。'),
(63992027, 'Double Cipher', '双重光波', '二重光波', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '①：场上的攻击力最高的怪兽在对方场上存在的场合，以自己场上的持有超量素材的1只「银河眼」超量怪兽或者「光波」超量怪兽为对象才能发动。那只超量怪兽的超量素材全部取除，把1只那只超量怪兽的同名怪兽从额外卡组特殊召唤。'),
(44436472, 'Double Coston', '双价体', 'ダブルコストン', 'Effect Monster', 'Zombie', 'DARK', 4, 1700, 1650, '①：暗属性怪兽上级召唤的场合，这张卡可以作为2只的数量解放。'),
(75652080, 'Double Cyclone', '二重旋风', 'ダブル・サイクロン', 'Spell Card', 'Quick-Play', NULL, NULL, NULL, NULL, '①：以自己场上1张魔法·陷阱卡和对方场上1张魔法·陷阱卡为对象才能发动。那些卡破坏。'),
(1607603, 'Double Dai', '大粗人们料想', '想定GUYS', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：可以从以下效果选择1个发动。 ●自己场上没有怪兽存在的场合才能发动。从卡组把1只战士族·4星怪兽特殊召唤。 ●以自己场上1只战士族怪兽为对象才能发动。把持有那只怪兽的等级以下的等级的1只战士族·地属性怪兽从自己的卡组·墓地特殊召唤。'),
(44883600, 'Double Defender', '二重防御者', 'ダブル・ディフェンダー', 'Spell Card', 'Continuous', NULL, NULL, NULL, NULL, '自己场上有表侧守备表示怪兽2只以上存在的场合，对方怪兽的攻击宣言时才能发动。把那1只对方怪兽的攻击无效。这个效果1回合只能使用1次。'),
(93612434, 'Double Disruptor Dragon', '双持手枪龙', 'デュアルウィール・ドラゴン', 'Effect Monster', 'Dragon', 'DARK', 8, 2500, 1500, '这个卡名的①②的效果1回合各能使用1次。 ①：把这张卡解放，以自己墓地2只卡名不同的「弹丸」怪兽为对象才能发动。那些怪兽守备表示特殊召唤。 ②：把墓地的这张卡除外才能发动。从自己的卡组·墓地选1张「速射扳机」或者「重型扳机」加入手卡。'),
(13166648, 'Double Dragon Descent', '双龙降临', '双龍降臨', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '对方的超量怪兽的直接攻击宣言时才能发动。从额外卡组把1只龙族·光属性的超量怪兽表侧攻击表示特殊召唤，攻击对象转移为那只怪兽进行伤害计算。这个效果特殊召唤的怪兽的攻击力变成和攻击怪兽的攻击力相同数值，效果无效化。「双龙降临」在1回合只能发动1张。'),
(28355719, 'Double Dude Token', '命运英雄 双身人', 'D-HERO ダブルガイ', 'Token', 'Warrior', NULL, NULL, NULL, NULL, NULL),
(35479109, 'Double Dust Tornado Twins', '沙尘之大飓风', '砂塵の大ハリケーン', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：以自己的魔法与陷阱区域盖放的卡任意数量为对象才能发动。盖放的那些卡和这张卡回到持有者手卡。那之后，自己可以把这个效果回到自己手卡的卡数量的魔法·陷阱卡从手卡盖放。'),
(38179121, 'Double Evolution Pill', '究极进化药', '究極進化薬', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：从自己的手卡·墓地把恐龙族怪兽和恐龙族以外的怪兽各1只除外才能发动。从手卡·卡组把1只7星以上的恐龙族怪兽无视召唤条件特殊召唤。'),
(300103005, 'Double Evolution Pill (Skill Card)', NULL, NULL, 'Skill Card', 'Rex', NULL, NULL, NULL, NULL, NULL),
(81881839, 'Double Exposure', '双重曝光', '二重露光', 'Spell Card', 'Continuous', NULL, NULL, NULL, NULL, '这个卡名的①②的效果1回合各能使用1次。 ①：以场上2只6星以下的同名怪兽为对象才能发动。那些怪兽的等级变成2倍。 ②：自己·对方的战斗阶段开始时，以自己场上1只「光波」怪兽为对象才能发动。选那只怪兽以外的场上1只表侧表示怪兽，直到结束阶段那个卡名当作和作为对象的「光波」怪兽同名卡使用。'),
(64319467, 'Double Fin Shark', '双生鳍鲨', 'ダブルフィン・シャーク', 'Effect Monster', 'Fish', 'WATER', 4, 1000, 1200, '这张卡召唤成功时，可以从自己墓地选择1只3星或者4星的鱼族·水属性怪兽表侧守备表示特殊召唤。这个效果特殊召唤的怪兽的效果无效化。这个效果发动的回合，自己不能把水属性以外的怪兽特殊召唤。'),
(10218411, 'Double Fusion', '二重融合', '二重融合', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '①：支付500基本分才能发动。自己的手卡·场上的怪兽作为融合素材，把1只融合怪兽融合召唤。那之后，可以把自己的手卡·场上的怪兽作为融合素材，把1只融合怪兽融合召唤。'),
(146746, 'Double Headed Anger Knuckle', '机关重连 愤怒钩舌', '機関重連アンガー・ナックル', 'Link Monster', 'Machine', 'EARTH', NULL, 1500, NULL, '机械族怪兽2只 这个卡名的①②的效果1回合只能有1次使用其中任意1个。这张卡不能作为连接素材。 ①：自己·对方的主要阶段，把自己的手卡·场上1只怪兽送去墓地，以自己墓地1只机械族·10星怪兽为对象才能发动。那只怪兽守备表示特殊召唤。这个效果特殊召唤的怪兽的效果无效化。 ②：这张卡在墓地存在的场合，把自己的手卡·场上1张卡送去墓地才能发动。这张卡特殊召唤。'),
(73239437, 'Double Hero Attack', '二重英雄攻击', 'ダブルヒーローアタック', 'Spell Card', 'Quick-Play', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：自己场上有需以「元素英雄 新宇侠」为融合素材的融合怪兽存在的场合，以自己墓地1只「英雄」融合怪兽为对象才能发动。那只怪兽无视召唤条件特殊召唤。'),
(6214163, 'Double Hooking', '双重上钩', 'ダブル・フッキング', 'Trap Card', 'Continuous', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：丢弃1张手卡，以自己墓地最多2只怪兽为对象才能把这张卡发动。那些怪兽特殊召唤。作为对象的怪兽从场上离开时这张卡破坏。这张卡从场上离开时作为对象的怪兽破坏。'),
(38129297, 'Double Interlock', '双重扳机', 'ダブル・トリガー', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '①：可以从以下效果选择1个发动（这个卡名的以下效果1回合各能选择1次）。 ●包含「弹丸」怪兽的自己墓地的怪兽作为融合素材除外，把1只融合怪兽融合召唤。 ●等级合计直到变成仪式召唤的怪兽的等级以上为止，把包含「弹丸」怪兽的自己墓地的怪兽除外，从手卡把1只仪式怪兽仪式召唤。'),
(49684352, 'Double Iris Magician', '虹彩的魔术师', '虹彩の魔術師', 'Pendulum Effect Monster', 'Spellcaster', 'DARK', 4, 1500, 1000, '这张卡在规则上也当作「灵摆龙」卡使用。 ①：这张卡被战斗·效果破坏的场合才能发动。从卡组把1张「灵摆读阵」卡加入手卡。'),
(72621670, 'Double Magical Arm Bind', '二重魔术臂束缚', 'ダブルマジックアームバインド', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '①：把自己场上2只怪兽解放，以对方场上2只表侧表示怪兽为对象才能发动。那2只表侧表示怪兽的控制权直到自己结束阶段得到。'),
(94770493, 'Double or Nothing!', '加倍机会', 'ダブル・アップ・チャンス', 'Spell Card', 'Quick-Play', NULL, NULL, NULL, NULL, '①：怪兽的攻击无效时，以那1只怪兽为对象才能发动。这次战斗阶段中，那只怪兽再1次可以攻击。这个效果让那只怪兽攻击的伤害步骤内，那只怪兽的攻击力变成2倍。'),
(5914184, 'Double Payback', '倍返', '倍返し', 'Trap Card', 'Continuous', NULL, NULL, NULL, NULL, '对方的卡的效果让自己受到1000以上的伤害时才能发动。那个时候受到的伤害每有1000，给这张卡放置1个倍倍指示物。下次的对方回合的结束阶段时，这张卡破坏并给与对方基本分这张卡放置的倍倍指示物数量×2000的数值的伤害。'),
(60832978, 'Double Resonator', '双头共鸣者', 'ダブル・リゾネーター', 'Tuner Monster', 'Fiend', 'FIRE', 1, NULL, NULL, '「双头共鸣者」的②的效果1回合只能使用1次。 ①：这张卡召唤·特殊召唤成功的场合，以场上1只表侧表示怪兽为对象才能发动。这个回合，那只表侧表示怪兽当作调整使用。 ②：把墓地的这张卡除外，以自己场上1只恶魔族怪兽为对象才能发动。这个回合，那只恶魔族怪兽当作调整使用。'),
(17643265, 'Double Shark', '双头鲨', 'ツーヘッド・シャーク', 'Effect Monster', 'Fish', 'WATER', 4, 1200, 1600, '这张卡召唤成功时，可以让自己场上的全部鱼族·4星怪兽的等级下降1星。这张卡在同1次的战斗阶段中可以作2次攻击。'),
(3682106, 'Double Snare', '二重陷阱', 'ダブルトラップ', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '破坏场上表侧表示存在的含有（陷阱的效果无效化的效果）的1张卡。');